<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {Activity,ArrowDownToLine,ArrowUpRight,ChartNoAxesCombined,RefreshCw,ShieldCheck,BookOpen,Users,Clock3,Database,LogOut} from 'lucide-vue-next'
import {number,percent,seconds,eventLabels,type AnalyticsReport} from './types'
const username=ref(''),password=ref(''),identity=ref(''),authorized=ref(false),loading=ref(false),error=ref(''),denied=ref(false)
const days=ref(7),includeAdmins=ref(false),report=ref<AnalyticsReport>(),section=ref('overview');let token='',epoch=0,timer:ReturnType<typeof setInterval>|undefined
let renewal:Promise<{accessToken:string;user:{username:string}}|null>|undefined,sessionVersion=0
async function request<T>(path:string,options:RequestInit={}):Promise<T>{
 const send=()=>fetch('/api/reader/v1'+path,{...options,credentials:'include',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...options.headers}})
 let response=await send()
 if(response.status===401&&token&&authorized.value&&!path.startsWith('/auth/')){
  const generation=sessionVersion,owner=identity.value
  renewal??=fetch('/api/reader/v1/auth/refresh',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:'{}'})
    .then(async r=>r.ok?await r.json():null).catch(()=>null).finally(()=>{renewal=undefined})
  const next=await renewal
  if(generation!==sessionVersion)throw new Error('数据站会话已变化，请重新登录。')
  if(next?.accessToken&&next.user?.username===owner){token=next.accessToken;response=await send()}
 }
 const value=await response.json()
 if(!response.ok){if(response.status===401||response.status===403){token='';authorized.value=false;report.value=undefined}if(response.status===403)denied.value=true;throw new Error(value.message||'数据暂时无法读取，请重试。')}
 return value
}
async function verify(){const account=await request<{username:string;role:string}>('/product/account');if(account.role!=='ADMIN'){denied.value=true;token='';throw new Error('此数据站仅向管理员开放，请使用管理员账号登录。')}identity.value=account.username;authorized.value=true;await load()}
async function login(){if(loading.value)return;sessionVersion++;loading.value=true;error.value='';denied.value=false;try{const result=await request<{accessToken:string}>('/auth/login',{method:'POST',body:JSON.stringify({username:username.value,password:password.value,clientType:'web',deviceName:'酒馆数据站'})});password.value='';token=result.accessToken;await verify()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function load(){if(!authorized.value)return;const id=++epoch;loading.value=true;error.value='';try{const result=await request<AnalyticsReport>('/product/analytics/overview?days='+days.value+'&includeAdmins='+includeAdmins.value);if(id===epoch)report.value=result}catch(e){if(id===epoch)error.value=(e as Error).message}finally{if(id===epoch)loading.value=false}}
function lock(){epoch++;sessionVersion++;token='';authorized.value=false;identity.value='';report.value=undefined;error.value='';loading.value=false}
function download(){if(!report.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(report.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='酒馆-数据-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const trendMax=computed(()=>Math.max(1,...(report.value?.trends.map(t=>Math.max(t.users,t.tasks))||[])))
function points(key:'users'|'tasks'){const rows=report.value?.trends||[];return rows.map((row,i)=>`${30+i*940/Math.max(1,rows.length-1)},${190-row[key]/trendMax.value*150}`).join(' ')}
const nav=[{id:'overview',label:'产品概览',icon:ChartNoAxesCombined},{id:'behavior',label:'行为与转化',icon:Activity},{id:'quality',label:'运行与成本',icon:Clock3},{id:'users',label:'用户与留存',icon:Users}]
const stamp=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚无记录'
watch([days,includeAdmins],()=>{report.value=undefined;void load()})
onMounted(async()=>{try{const result=await request<{accessToken:string}>('/auth/refresh',{method:'POST',body:'{}'});token=result.accessToken;await verify()}catch{error.value=''}timer=setInterval(()=>{if(authorized.value&&!loading.value&&document.visibilityState==='visible')void load()},30000)})
onUnmounted(()=>{epoch++;clearInterval(timer);token=''})
</script>
<template>
 <div v-if="!authorized" class="insight-login"><div class="login-intro"><span class="eyebrow">TAVERN / INSIGHTS</span><h1>让每一次探索<br>都有迹可循。</h1><p>酒馆的独立数据站。观察用户如何进入故事、做出选择，以及系统如何回应。</p><span class="access-note"><ShieldCheck :size="18"/>仅管理员可访问</span></div><form class="login-card" @submit.prevent="login"><BookOpen :size="28"/><h2>登录数据站</h2><p>使用现有的产品管理员账号。</p><label>账号<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="loading">{{loading?'正在验证…':'进入数据站'}}<ArrowUpRight :size="17"/></button><small v-if="denied">普通用户不会获得任何数据访问权限。</small></form></div>
 <div v-else class="insight-layout">
  <aside class="insight-sidebar"><a class="insight-brand" href="/"><BookOpen :size="23"/><span>酒馆<small>INSIGHTS</small></span></a><span class="nav-caption">工作空间 / 内测</span><nav><button v-for="item in nav" :key="item.id" :class="{selected:section===item.id}" :aria-current="section===item.id?'page':undefined" @click="section=item.id"><component :is="item.icon" :size="18"/>{{item.label}}</button></nav><div class="sidebar-bottom"><span class="quota-badge">{{report?.unlimitedUsage?'所有账号 · 不限额度':'数据正在连接'}}</span><p><ShieldCheck :size="15"/>{{identity}}</p><button @click="lock"><LogOut :size="15"/>锁定数据站</button></div></aside>
  <main><header class="insight-header"><div><span class="eyebrow">PRODUCT ANALYTICS</span><h1>{{nav.find(n=>n.id===section)?.label}}</h1><p>真实行为与执行回执，更新于 {{report?stamp(report.generatedAt):'读取中'}}</p></div><div class="header-actions"><label class="sr-only" for="days">统计范围</label><select id="days" v-model.number="days"><option :value="7">最近 7 天</option><option :value="30">最近 30 天</option><option :value="90">最近 90 天</option></select><button :disabled="loading" aria-label="刷新数据" @click="load"><RefreshCw :size="17" :class="{spinning:loading}"/></button><button :disabled="!report" @click="download"><ArrowDownToLine :size="16"/>导出 JSON</button></div></header>
   <div class="scope-bar"><span class="live-dot"></span>本地内测数据 · 上海时区<label><input type="checkbox" v-model="includeAdmins">包含管理员测试数据</label><span>显式排除名单始终生效</span></div>
   <p v-if="error" role="alert" class="error error-panel">{{error}} <button @click="load">重新读取</button></p>
   <div v-if="!report&&!error" class="loading-panel" role="status">正在汇总行为和服务端回执…</div>
   <template v-if="report">
    <p v-if="report.quality.eventsTruncated||report.quality.tasksTruncated||report.quality.usageTruncated||report.quality.imagesTruncated" class="warning" role="alert">当前窗口的数据达到查询上限，以下为部分样本。请缩短统计范围；此窗口不能作为完整统计。</p>
    <template v-if="section==='overview'">
     <div class="metric-grid"><article><span>活跃账号</span><strong>{{number(report.summary.activeUsers)}}</strong><small>{{number(report.summary.newAccounts)}} 个新账号 / {{number(report.summary.accounts)}} 个纳入统计</small></article><article><span>页面访问</span><strong>{{number(report.summary.pageViews)}}</strong><small>{{number(report.summary.visitors)}} 个浏览器 / {{number(report.summary.sessions)}} 次会话</small></article><article><span>已受理任务</span><strong>{{number(report.summary.tasks)}}</strong><small>包含文字、出图和核验任务</small></article><article><span>终态成功率</span><strong>{{percent(report.summary.successRate)}}</strong><small>成功 ÷（成功 + 失败）</small></article></div>
     <section class="insight-panel"><div class="panel-heading"><div><h2>探索的节奏</h2><p>每日活跃账号与受理任务</p></div><div class="legend"><span>● 活跃账号</span><span>● 任务</span></div></div><svg class="trend" viewBox="0 0 1000 230" role="img" aria-label="每日活跃用户与任务趋势"><g stroke="#e7ecef"><path d="M30 40H970 M30 115H970 M30 190H970"/></g><text x="0" y="35">{{trendMax}}</text><polyline :points="points('tasks')" fill="none" stroke="#adb9cd" stroke-width="3"/><polyline :points="points('users')" fill="none" stroke="#168978" stroke-width="3"/><text x="30" y="224">{{report.trends[0]?.day}}</text><text x="970" y="224" text-anchor="end">{{report.trends.at(-1)?.day}}</text></svg><details><summary>查看每日数据</summary><div class="table-scroll"><table><thead><tr><th>日期</th><th>活跃账号</th><th>访问</th><th>任务</th><th>成功 / 失败</th></tr></thead><tbody><tr v-for="t in report.trends" :key="t.day"><td>{{t.day}}</td><td>{{t.users}}</td><td>{{t.pageViews}}</td><td>{{t.tasks}}</td><td>{{t.succeeded}} / {{t.failed}}</td></tr></tbody></table></div></details></section>
     <div class="panel-grid"><section class="insight-panel"><h2>作品使用</h2><div class="table-scroll"><table><thead><tr><th>作品</th><th>打开 / 进入</th><th>任务</th><th>成功</th></tr></thead><tbody><tr v-for="w in report.works" :key="w.worldId"><td>{{w.title}}</td><td>{{w.views}}</td><td>{{w.tasks}}</td><td>{{w.succeeded}}</td></tr></tbody></table></div><p v-if="!report.works.length" class="empty">尚无作品活动。新埋点不会回填历史行为。</p></section><section class="insight-panel"><h2>访问页面</h2><div v-for="p in report.pages" :key="p.path" class="stat-row"><code>{{p.path}}</code><strong>{{number(p.views)}}</strong></div><p v-if="!report.pages.length" class="empty">尚无访问记录。</p></section></div>
    </template>
    <template v-if="section==='behavior'">
     <section class="insight-panel"><div class="panel-heading"><div><h2>从进入到回应</h2><p>按账号去重，依次发生才计入下一步。</p></div></div><div class="funnel"><article v-for="(step,index) in report.funnel" :key="step.label"><span>0{{index+1}} / {{step.label}}</span><strong>{{step.users}}</strong><div class="funnel-bar" :style="{width:Math.max(3,step.users/Math.max(1,report.funnel[0]?.users||0)*100)+'%'}"></div><small>{{index?'上一步转化 '+percent(step.conversion):'所选时间范围内的账号'}}</small></article></div><p class="note">{{report.quality.funnelBasis}}</p></section>
     <div class="panel-grid"><section class="insight-panel"><h2>关键行为</h2><table><thead><tr><th>交互</th><th>次数</th><th>账号数</th></tr></thead><tbody><tr v-for="e in report.events.filter(e=>e.name!=='page.engaged')" :key="e.name"><td>{{eventLabels[e.name]||e.name}}</td><td>{{e.count}}</td><td>{{e.users}}</td></tr></tbody></table><p v-if="!report.events.length" class="empty">尚无行为事件。</p></section><section class="insight-panel"><h2>停留与场景</h2><div class="stat-row"><span>前台累计停留</span><strong>{{(report.summary.engagedMs/60000).toFixed(1)}} 分钟</strong></div><div class="stat-row"><span>图像资产记录</span><strong>{{report.images.records}}</strong></div><div class="stat-row"><span>复用的空环境资产</span><strong>{{report.images.reusedAssets}}</strong></div><p class="note">停留仅累计前台页面；后台标签页不计时。图像资产数量包含复用记录，不等于付费调用次数。</p></section></div>
    </template>
    <template v-if="section==='quality'">
     <div class="panel-grid"><section class="insight-panel"><h2>响应时间</h2><table><thead><tr><th>阶段</th><th>中位数</th><th>P95</th><th>样本</th></tr></thead><tbody><tr v-for="(label,key) in {firstText:'任务到首段文字',total:'任务到终态',provider:'供应商调用'}" :key="key"><td>{{label}}</td><td>{{seconds(report.timings[key].medianMs)}}</td><td>{{seconds(report.timings[key].p95Ms)}}</td><td>{{report.timings[key].samples}}</td></tr></tbody></table><p class="note">样本缺失显示 —；中位数和 P95 仅来自有回执的任务。任务总耗时包含排队与核验。</p></section><section class="insight-panel"><h2>任务状态</h2><div v-for="(count,state) in report.taskStates" :key="state" class="stat-row"><code>{{state}}</code><strong>{{count}}</strong></div><p v-if="!Object.keys(report.taskStates).length" class="empty">暂无任务。</p></section></div>
     <section class="insight-panel"><h2>模型用量与已知费用</h2><div class="usage-strip"><span><strong>{{number(report.usage.calls)}}</strong> 调用记录</span><span><strong>{{number(report.usage.inputTokens)}}</strong> 输入 tokens</span><span><strong>{{number(report.usage.outputTokens)}}</strong> 输出 tokens</span></div><div class="table-scroll"><table><thead><tr><th>通道</th><th>调用</th><th>输入 tokens</th><th>输出 tokens</th></tr></thead><tbody><tr v-for="m in report.usage.models" :key="m.profileId"><td>{{m.name}}<small>{{m.modelId}}</small></td><td>{{m.calls}}</td><td>{{number(m.inputTokens)}}</td><td>{{number(m.outputTokens)}}</td></tr></tbody></table></div><p v-if="!report.usage.costs.length" class="note">尚无可核验的供应商金额。</p><p v-for="cost in report.usage.costs" :key="cost.currency" class="cost">{{cost.currency}} {{cost.amount}}</p><p class="note">{{report.quality.costBasis}} {{report.usage.unknownCostRecords}} 笔费用未知，{{report.usage.unknownTokenRecords}} 笔 token 用量不完整。</p></section>
     <section class="insight-panel"><h2>需要关注的错误 · 服务端回执</h2><div v-for="e in report.errors" :key="e.code" class="stat-row"><code>{{e.code}}</code><strong>{{e.count}}</strong></div><p v-if="!report.errors.length" class="empty">所选窗口内没有任务错误回执。</p></section><section class="insight-panel"><h2>浏览器报告的错误</h2><p class="note">客户端线索，与服务端任务回执分别统计。浏览器 API 耗时中位数 {{seconds(report.clientLatency.medianMs)}}，P95 {{seconds(report.clientLatency.p95Ms)}}。</p><div v-for="(e,i) in report.clientErrors" :key="i" class="stat-row"><code>{{e.status||'—'}} · {{e.path}} · {{e.code}}</code><strong>{{e.count}}</strong></div><p v-if="!report.clientErrors.length" class="empty">尚无客户端错误记录。</p></section>
    </template>
    <template v-if="section==='users'">
     <section class="insight-panel"><h2>用户使用情况</h2><div class="table-scroll"><table><thead><tr><th>账号</th><th>角色</th><th>最后活动</th><th>任务</th><th>成功 / 失败</th></tr></thead><tbody><tr v-for="u in report.users" :key="u.id"><td>{{u.username}}</td><td>{{u.role}}</td><td>{{stamp(u.lastSeenAt)}}</td><td>{{u.tasks||0}}</td><td>{{u.succeeded||0}} / {{u.failed||0}}</td></tr></tbody></table></div></section>
     <section class="insight-panel"><h2>次日留存 · D1</h2><p class="note">{{report.quality.retentionBasis}}</p><table><thead><tr><th>首次采集日</th><th>账号数</th><th>次日回访</th><th>留存率</th></tr></thead><tbody><tr v-for="r in report.retention" :key="r.day"><td>{{r.day}}</td><td>{{r.users}}</td><td>{{r.returned??'待观察'}}</td><td>{{percent(r.d1)}}</td></tr></tbody></table></section>
    </template>
    <footer><Database :size="14"/>不采集对话正文、记忆内容、密码或密钥。页面与点击为客户端线索，执行结果以服务端记录为准。每 30 秒刷新。</footer>
   </template>
  </main>
 </div>
</template>
